var records=[];['Light/Clean','Dark/Clean'].forEach(function(app){var page=doc.pages.find(function(p){return p.name==='Proto macOS '+app.split('/')[0];});var s=page.layers.find(function(l){return l.name==='Screen/macos/'+app+'/artifacts--detail';});var pop=s.layers.find(function(l){return l.name==='popover/Share';});pop.layers.forEach(function(r){var t=r.layers.find(function(l){return l.name==='text';});if(t){t.layers.filter(function(l){return l.type==='Text';}).forEach(function(l){l.frame.width=144;});t.stackLayout.apply();r.stackLayout.apply();}});pop.stackLayout.apply();records.push({app:app,frame:s.id,popover:{w:pop.frame.width,h:pop.frame.height}});});console.log(JSON.stringify(records));